/* ---------- «Хорижий адабиёт» бўлими (#adabiyot) ----------
   Мавзулар ўқиш тартибида: асослардан мураккабга. Ҳар бир манба: таҳлил, дарсда қўлланиши,
   у асос бўлган дарслар ва текширилган ҳавола (DOI ёки расмий сайт). */
(() => {
  "use strict";
  const root = document.getElementById("adRoot");
  const D = window.EKO_ADABIYOT;
  if (!root || !D) return;
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const KINDS = { article: "📄 Илмий мақола", report: "📊 Халқаро ҳисобот", book: "📕 Китоб", textbook: "📗 Дарслик", standard: "📐 Стандарт", method: "🧠 Методика", law: "🇺🇿 Давлат ҳужжати" };
  const FILTERS = [["", "Барчаси"], ["sci", "Илмий иш ва ҳисобот"], ["book", "Китоб ва дарслик"], ["standard", "Стандарт"], ["method", "Таълим методикаси"], ["law", "Давлат ҳужжатлари"]];
  const inFilter = (x, f) => !f || (f === "sci" ? x.kind === "article" || x.kind === "report" : f === "book" ? x.kind === "book" || x.kind === "textbook" : x.kind === f);
  let filter = "", onlyOpen = false, q = "";

  const lessonTitle = (key) => {
    const [cid, li] = key.split(":");
    const c = window.EkoApp && EkoApp.courses.find((x) => x.id === cid);
    const l = c && c.lessons[Number(li)];
    return l ? { course: c.title, title: l.title } : null;
  };
  const stageOk = (x) => {
    const st = document.documentElement.classList.contains("stage-maktab") ? "maktab" : "uni";
    return x.level === "both" || x.level === st || st === "uni";
  };

  function card(x) {
    const ls = (x.lessons || []).map((k) => [k, lessonTitle(k)]).filter(([, t]) => t);
    return `<article class="ad-card" id="ad-${esc(x.id)}">
      <div class="ad-tags"><span class="ad-kind">${esc(KINDS[x.kind] || x.kind)}</span>${x.open ? `<span class="ad-open">🔓 Бепул ўқиш мумкин</span>` : ""}</div>
      <h4>${esc(x.title_uz)}</h4>
      <p class="ad-cite" data-notr>${esc(x.cite)}</p>
      <p class="ad-sum">${esc(x.summary)}</p>
      ${x.use ? `<p class="ad-use"><b>💡 Дарсда:</b> <span>${esc(x.use)}</span></p>` : ""}
      ${ls.length ? `<div class="ad-lessons"><span class="small muted">Шу манбага асосланган дарслар:</span>${ls.map(([k, t]) => `<button type="button" class="chip" data-ad-lesson="${esc(k)}" title="${esc(t.course)}">${esc(t.title)}</button>`).join("")}</div>` : ""}
      <a class="btn btn-ghost btn-sm ad-go" href="${esc(x.url)}" target="_blank" rel="noopener">↗ Манбани очиш</a>${x.doi ? `<span class="small muted ad-doi" data-notr>DOI: ${esc(x.doi)}</span>` : ""}
    </article>`;
  }

  function render() {
    const items = D.items.filter((x) => stageOk(x) && inFilter(x, filter) && (!onlyOpen || x.open) &&
      (!q || `${x.title_uz} ${x.cite} ${x.summary}`.toLowerCase().includes(q)));
    const body = D.topics.map((t, ti) => {
      const list = items.filter((x) => x.topic === t.id).sort((a, b) => a.order - b.order);
      if (!list.length) return "";
      return `<section class="ad-topic"><h3>${esc(t.t)}</h3><p class="muted">${esc(t.d)}</p><div class="ad-grid">${list.map(card).join("")}</div></section>`;
    }).join("");
    $box.innerHTML = body || `<p class="muted">Бундай манба топилмади.</p>`;
    $count.textContent = String(items.length);
  }

  const total = D.items.length, open = D.items.filter((x) => x.open).length, mapped = new Set(D.items.flatMap((x) => x.lessons || [])).size;
  root.innerHTML = `
    <span class="pill">🌍 Илмий асос · текширилган ҳаволалар</span>
    <h2 class="section-title">Хорижий адабиёт ва илмий манбалар</h2>
    <p class="muted">Платформадаги дарслар қайси илмий ишлар, халқаро ҳисоботлар, таълим методикалари ва давлат ҳужжатларига асосланганини шу ерда кўрасиз. Мавзулар ўқиш тартибида жойлашган: аввал асослар, кейин сув, ҳаво, иқлим, чиқиндилар, мониторинг ва сиёсат. Ҳар бир манбанинг қисқа таҳлили, дарсда қандай ишлатилиши ва асл манбага ҳавола берилган.</p>
    <div class="ad-stats"><div><b>${total}</b><span>манба</span></div><div><b>${open}</b><span>бепул ўқиш мумкин</span></div><div><b>${mapped}</b><span>дарс манбаларга боғланган</span></div><div><b>${D.topics.length}</b><span>мавзу</span></div></div>
    <div class="ad-tools">
      <div class="filters" id="adFilters">${FILTERS.map(([k, n]) => `<button type="button" class="chip${k === "" ? " active" : ""}" data-adf="${k}">${esc(n)}</button>`).join("")}</div>
      <label class="ad-only"><input type="checkbox" id="adOpen"> <span>Фақат бепул</span></label>
      <input class="search" id="adSearch" type="search" placeholder="🔍 Манба қидириш…" aria-label="Манба қидириш">
      <span class="small muted">Топилди: <b id="adCount"></b></span>
    </div>
    <div id="adBox"></div>
    <p class="small muted ad-note">Ҳаволалар DOI (рақамли объект идентификатори) ёки ташкилотнинг расмий сайти орқали берилган ва текширилган. Пулли журнал мақолаларининг аннотацияси ҳамма учун очиқ; тўлиқ матнни университет кутубхонаси орқали ёки муаллифдан сўраб олиш мумкин.</p>`;
  const $box = root.querySelector("#adBox"), $count = root.querySelector("#adCount");
  root.querySelector("#adFilters").addEventListener("click", (e) => {
    const b = e.target.closest("[data-adf]"); if (!b) return;
    filter = b.dataset.adf;
    root.querySelectorAll("[data-adf]").forEach((x) => x.classList.toggle("active", x === b));
    render();
  });
  root.querySelector("#adOpen").addEventListener("change", (e) => { onlyOpen = e.target.checked; render(); });
  root.querySelector("#adSearch").addEventListener("input", (e) => { q = e.target.value.trim().toLowerCase(); render(); });
  root.addEventListener("click", (e) => {
    const b = e.target.closest("[data-ad-lesson]"); if (!b || !window.EkoApp) return;
    const [cid, li] = b.dataset.adLesson.split(":");
    EkoApp.openLesson(cid, Number(li));
  });
  /* Дарс ойнасидаги «Барча манбалар» ҳаволаси: ойнани ёпиб, бўлимни очамиз */
  document.addEventListener("click", (e) => {
    const a = e.target.closest('.lesson-refs a[href="#adabiyot"]');
    if (!a) return;
    e.preventDefault();
    const dlg = a.closest("dialog");
    if (dlg && dlg.open) dlg.close();
    if (window.EkoNav) EkoNav.go("adabiyot"); else location.hash = "#adabiyot";
  });
  window.addEventListener("eko:stage", () => setTimeout(render, 0));
  render();
})();
